INSERT INTO `article_news` VALUES (1,1,'Bienvenue sur UpcycleConnect',NULL,'CA MARCHEEEEE',NULL,'Tutoriel','valide','2026-04-13 17:19:04'),(5,1,'5 astuces pour upcycler vos vieilles palettes',NULL,'Le bois de palette est un matériau incroyable pour l\'upcycling. Dans cet article, découvrez comment construire une table basse, des étagères ou même un canapé d\'extérieur avec de simples palettes de récupération. N\'oubliez pas de poncer et de traiter le bois pour qu\'il résiste en extérieur !','https://images.unsplash.com/photo-1556910103-1c02745aae4d?w=500','','valide','2026-04-20 17:52:24'),(6,1,'Pourquoi l\'upcycling est l\'avenir de la mode',NULL,'L\'industrie textile est l\'une des plus polluantes au monde. L\'upcycling propose une alternative forte : prendre de vieux vêtements pour en recréer de nouveaux avec un design unique. Des créateurs du monde entier se lancent dans cette tendance qui allie style et écologie. Découvrez notre sélection de marques pionnières.','https://images.unsplash.com/photo-1550614000-4b95d4ebf071?w=500','annonce','valide','2026-04-15 08:30:00'),(7,1,'Comment restaurer un vieux meuble en bois ?',NULL,'Vous avez trouvé une vieille commode dans le grenier de vos grands-parents ? Ne la jetez surtout pas ! Avec un peu de papier de verre, de la peinture écologique et de nouvelles poignées, vous pouvez la transformer en une pièce maîtresse de votre salon. Suivez notre guide pas à pas pour un résultat professionnel.','https://images.unsplash.com/photo-1533090481720-856c6e3c1fdc?w=500','MAJ','brouillon','2026-04-18 12:15:00'),(8,1,'Le plastique recyclé s\'invite dans votre cuisine',NULL,'Saviez-vous que vos anciennes bouteilles en plastique peuvent devenir de magnifiques ustensiles de cuisine ou des plans de travail robustes ? L\'innovation technologique permet aujourd\'hui de compresser et fondre le plastique pour lui donner une seconde vie incroyable. Focus sur cette nouvelle tendance de décoration intérieure.','https://images.unsplash.com/photo-1605600659908-0ef719419d41?w=500','TEST','valide','2026-04-19 07:00:00'),(9,20,'QWRFWEF',NULL,'EASFEWSFWSEsss',NULL,'Conseil pratique','en attente','2026-05-10 10:51:19'),(12,43,'Test Upload',NULL,'abc','uploads/articles/2355db878786bf426f3675880a2653f4.jpg','conseil','brouillon','2026-06-30 20:43:27'),(13,43,'CleanUploadTest',NULL,'xyz','uploads/articles/1562cd250217cf35c987152a4cbc2806.jpg','conseil','brouillon','2026-06-30 20:47:31');
/*!40000 ALTER TABLE `article_news` ENABLE KEYS */;
